#!/usr/bin/env python3
"""Check reviewed wrapper bytes before executing Gradle (not a trust boundary).

Updates require reviewing all four files and updating these pins together.
The properties digest pins the complete file, not an approximate Java parser.
"""

import argparse
import hashlib
import stat
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
# Launchers and JAR match files generated by the Gradle 9.7.1 bin distribution
# (ZIP SHA-256 acd53f1edaf02f1a8ff99879f8a34b302661a057d9b063ae9e35b552f804d20a).
# The properties pin is repository-specific, including distribution URL and hash.
PINS = {
    "gradlew": "a5a5c199ba02189ae8c46a334223371a20599d9c298ef65e7540ede4a3f72d59",
    "gradlew.bat": "d539676c48b596afda64c963ec8f7ee56c7b3fe7e3b81d1dbe2d1a1e3dd9e9f8",
    "gradle/wrapper/gradle-wrapper.jar": "7a9ce74cff467ca1bf60a4fcd9f05185acceda4d0f382434d393e17864262c5d",
    "gradle/wrapper/gradle-wrapper.properties": "d0bebe8133babb74ab29a31ee6616c56ef8985fc801e1fd16c61b5ed2189e907",
}


def verify(root: Path) -> list[str]:
    errors = []
    try:
        if not stat.S_ISDIR(root.lstat().st_mode):
            return [f"{root}: checkout root is not a directory (symlinks forbidden)"]
    except OSError as exc:
        return [f"{root}: cannot inspect checkout root: {exc}"]
    for name, expected in PINS.items():
        try:
            path = root
            parts = Path(name).parts
            for part in parts[:-1]:
                path = path / part
                if not stat.S_ISDIR(path.lstat().st_mode):
                    raise ValueError(f"{path}: parent is not a directory (symlinks forbidden)")
            path = path / parts[-1]
            if not stat.S_ISREG(path.lstat().st_mode):
                raise ValueError(f"{path}: not a regular file (symlinks forbidden)")
            actual = hashlib.sha256(path.read_bytes()).hexdigest()
        except (OSError, ValueError) as exc:
            errors.append(f"{name}: cannot read: {exc}")
            continue
        if actual != expected:
            errors.append(f"{name}: SHA-256 mismatch (expected {expected}, got {actual})")
    return errors


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=ROOT, help="checkout root")
    args = parser.parse_args()
    errors = verify(args.root)
    if errors:
        for error in errors:
            print(f"wrapper integrity FAILED: {error}", file=sys.stderr)
        return 1
    print("wrapper integrity PASSED")
    return 0


if __name__ == "__main__":
    sys.exit(main())
